  chartLegendConfig={{
    series1Label: "Product A",
    series2Label: "Product B",
    series3Label: "Product C",
  }}
  barGroupConfig={{
    yAxis: true,
    yAxisConfig: { tickCount: 6 },
    barWidth: "M",
  }}
