  data={data}
  chartLegend={true}
  chartLegendConfig={{
    size: 'L', // Larger legend text
  }}
/>

// Combine static and interactive DataHead
<VerticalMultiBarChart
  data={data}
  chartLegend={true}
  chartLegendConfig={{
    series1Label: 'Product A',
    series2Label: 'Product B',
    type: 'dashed',
    size: 'M',
    dataHead: true,
    dataHeadConfig: {
      dataLeadValue: 1234, // Static total shown by default
      supportingLabelValue: 'Total',
    },
    interactiveDataHead: true, // Updates to per-category value on hover
    formatHoverSupportingLabel: (category, seriesIndex) => `${category}`,
  }}
